// QA-2 (command injection): the base-scanner ffprobe arg-slice boundary
// regression. ffprobe is launched via exec.CommandContext with the path as ONE
// argv element (conventions.md hard rule 11; golang-security) — NEVER a shell.
// This test proves that property with a sentinel: the path passed to probe is a
// shell command-substitution that would create a sentinel file IF a shell
// expanded it. After probing, the sentinel MUST NOT exist (and probe soft-fails,
// since the literal path is not a real file). If anyone ever regresses probe to
// `sh -c`, the `$(...)` executes and the sentinel appears.
//
// The path is passed directly to probe as a Go string (one argv element by Go
// exec construction); no on-disk fixture with the payload name is needed. The
// coder's ffprobe_test.go covers the soft-fail failure modes (missing binary,
// non-zero exit, directory) but not shell-metacharacter safety, so this is a
// genuinely different boundary (not redundant).
package main

import (
	"context"
	"os"
	"os/exec"
	"path/filepath"
	"testing"
)

// TestQA_Probe_ArgSliceNoShellExpansion is the AC-2 / golang-security
// command-injection regression for the base-scanner ffprobe boundary.
func TestQA_Probe_ArgSliceNoShellExpansion(t *testing.T) {
	if _, err := exec.LookPath(ffprobeBin); err != nil {
		t.Skip("ffprobe not on PATH — arg-slice regression needs ffprobe to actually run")
	}

	sentinel := filepath.Join(t.TempDir(), "qa-pwned-sentinel")

	// The path passed to probe. As ONE argv element (Go exec) ffprobe receives
	// the literal string "$(touch <sentinel>)" — a file that does not exist, so
	// it soft-fails. If probe regressed to `sh -c "ffprobe ... $path"`, the
	// $(touch <sentinel>) substitution would execute and create the sentinel.
	injPath := "$(touch " + sentinel + ")"

	data, warning, err := probe(context.Background(), injPath)
	if err != nil {
		t.Fatalf("probe err = %v, want nil (probe is all-soft)", err)
	}
	if len(data) != 0 {
		t.Fatalf("probe data = %d bytes, want empty (the payload path is not a real file)", len(data))
	}
	if warning == "" {
		t.Fatal("probe warning empty, want non-empty (ffprobe failed on the payload path)")
	}

	// The load-bearing assertion: NO shell ran, so the sentinel was never created.
	if _, statErr := os.Stat(sentinel); statErr == nil {
		t.Fatal("QA command-injection: sentinel file was created — probe shelled out and expanded the payload (arg-slice regression)")
	} else if !os.IsNotExist(statErr) {
		t.Fatalf("stat sentinel: %v", statErr)
	}
}
